/* glibc's own header for the interface joistmig's stubs are written to
   (the owner's decision, 2026-11-06: written for glibc, apart from Joist's
   header for its own programs; the two agree on the names below and on
   the message, nothing else).

   A message's body is the routine's in-line arguments in declaration
   order, each at an 8-byte boundary; a variable array is its count (a
   word) and then its elements.  The first three words of the body go in
   message registers 1-3, the rest in the thread's IPC buffer; register 0
   carries the routine's id (a request) or its return code (a reply) in
   its low half and the body's length in bytes in its high half.  A
   message passes up to two rights.

   Here a right to send is kept with its MIG disposition, so that
   joist_mig_call (joist-mig.c) can make it from the name table: a send
   right made from a receive right, a copy, or a move that gives up one
   user reference.  */

#ifndef _JOIST_MIG_H
#define _JOIST_MIG_H 1

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#define JOIST_MIG_BUF_WORDS	512u		/* the IPC buffer */
#define JOIST_MIG_WORDS		(JOIST_MIG_BUF_WORDS + 3u)
#define JOIST_MIG_CAPS		2u

/* MIG's results (mach/mig_errors.h's values).  */
#define JOIST_MIG_TYPE_ERROR		(-300)
#define JOIST_MIG_REPLY_MISMATCH	(-301)
#define JOIST_MIG_BAD_ID		(-303)
#define JOIST_MIG_BAD_ARGUMENTS		(-304)
#define JOIST_MIG_NO_REPLY		(-305)
#define JOIST_MIG_ARRAY_TOO_LARGE	(-307)

struct joist_mig_msg
{
  uint64_t r[4];
  uint32_t ncaps;
  uint32_t cap[JOIST_MIG_CAPS];	/* names: what to send, or where it came */
  uint8_t disp[JOIST_MIG_CAPS];	/* to send: the MIG disposition */
  uint32_t len;			/* words in BUF */
  uint64_t *buf;		/* JOIST_MIG_BUF_WORDS words */
  uint64_t badge;		/* received: the sender's badge */
};

/* A server's routine (what <demuxer>_routine returns for a message's id;
   MIG's mig_routine_t, on Joist messages).  */
typedef void (*joist_mig_routine_t) (struct joist_mig_msg *in,
				     struct joist_mig_msg *out);

/* The runtime's (joist-mig.c), under glibc's reserved names: generated
   code says joist_mig_*, which a program may use for itself.  */
#define joist_mig_call __joist_mig_call
#define joist_mig_allocate __joist_mig_allocate
#define joist_mig_deallocate __joist_mig_deallocate

/* A call on the port named PORT, the reply in *M; 0 or a Mach error.  */
extern int joist_mig_call (uint32_t port, struct joist_mig_msg *m);
/* Memory for what MIG would have sent out of line, and its release.  */
extern void *joist_mig_allocate (size_t size);
extern void joist_mig_deallocate (void *p, size_t size);

/* A body being built or read: bytes [0, END), the next field at AT.  */
struct joist_mig_body
{
  uint64_t w[JOIST_MIG_WORDS];
  size_t at, end;
};

/* The 8-byte boundary at or after N.  */
static inline size_t
joist_mig_align (size_t n)
{
  return (n + 7) & ~(size_t) 7;
}

/* Add N bytes from P: -1 if they don't fit.  */
static inline int
joist_mig_put (struct joist_mig_body *b, const void *p, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > sizeof b->w || n > sizeof b->w - start)
    return -1;
  memcpy ((unsigned char *) b->w + start, p, n);
  b->end = b->at = start + n;
  return 0;
}

/* Take N bytes into P: -1 if fewer are left.  */
static inline int
joist_mig_get (struct joist_mig_body *b, void *p, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > b->end || n > b->end - start)
    return -1;
  memcpy (p, (const unsigned char *) b->w + start, n);
  b->at = start + n;
  return 0;
}

/* The next N bytes where they are: NULL if fewer are left.  */
static inline void *
joist_mig_ref (struct joist_mig_body *b, size_t n)
{
  size_t start = joist_mig_align (b->at);
  if (start > b->end || n > b->end - start)
    return NULL;
  b->at = start + n;
  return (unsigned char *) b->w + start;
}

/* The id or return code in register 0.  */
static inline uint32_t
joist_mig_code (const struct joist_mig_msg *m)
{
  return (uint32_t) (m->r[0] & 0xffffffffu);
}

/* B into M: its length beside the code, three words in registers, the
   rest in the buffer.  */
static inline void
joist_mig_send (struct joist_mig_msg *m, const struct joist_mig_body *b)
{
  size_t nw = joist_mig_align (b->end) / 8;
  m->r[0] = (m->r[0] & 0xffffffffu) | ((uint64_t) b->end << 32);
  m->r[1] = nw > 0 ? b->w[0] : 0;
  m->r[2] = nw > 1 ? b->w[1] : 0;
  m->r[3] = nw > 2 ? b->w[2] : 0;
  m->len = nw > 3 ? (uint32_t) (nw - 3) : 0;
  if (m->len > 0)
    memcpy (m->buf, &b->w[3], (size_t) m->len * 8);
}

/* M's body into B, to read: -1 if its length can't be what came (more
   than a message holds, or not the words that arrived).  */
static inline int
joist_mig_recv (const struct joist_mig_msg *m, struct joist_mig_body *b)
{
  size_t bytes = (size_t) (m->r[0] >> 32);
  size_t nw = joist_mig_align (bytes) / 8;
  if (m->ncaps > JOIST_MIG_CAPS || m->len > JOIST_MIG_BUF_WORDS
      || nw > JOIST_MIG_WORDS || m->len != (nw > 3 ? nw - 3 : 0))
    return -1;
  b->w[0] = m->r[1];
  b->w[1] = m->r[2];
  b->w[2] = m->r[3];
  if (m->len > 0)
    memcpy (&b->w[3], m->buf, (size_t) m->len * 8);
  b->at = 0;
  b->end = bytes;
  return 0;
}

/* The right NAME, with MIG's DISPOSITION, sent with M: -1 if M has its
   two already.  */
static inline int
joist_mig_right (struct joist_mig_msg *m, uint32_t name, int disposition)
{
  if (m->ncaps >= JOIST_MIG_CAPS)
    return -1;
  m->cap[m->ncaps] = name;
  m->disp[m->ncaps] = (uint8_t) disposition;
  m->ncaps++;
  return 0;
}

/* Bulk data through the caller's windows (Joist's decision 0032, Phase 5
   step 9).  A variable array that doesn't fit in line goes through a
   window: its count word has JOIST_MIG_OOL set, and the next word is its
   byte offset there.  An in array is in the client's read window, which
   the server copies from (joist_mig_reply_read); an out array goes into
   the slice of the client's write window the request offered for it (two
   words at its place in the request: the slice's bytes, 0 for none, and
   its offset), which the server copies into (joist_mig_reply_write).  A
   copy call moves at most JOIST_MIG_COPY_MAX bytes; a call carries at
   most JOIST_MIG_WINDOW_MAX through each window.  */
#define JOIST_MIG_COPY_MAX	65536u		/* the kernel's JOIST_COPY_MAX */
#define JOIST_MIG_WINDOW_MAX	(8u * 1024u * 1024u)	/* the owner, 2026-11-16 */
/* The write window offered for an out array whose size the client can't
   bound before the call (0032's open question; the owner, 2026-11-16: a
   default, one copy call): data past it is refused, never cut short.  */
#define JOIST_MIG_OUT_DEFAULT	65536u
#define JOIST_MIG_OOL		((uint64_t) 1 << 63)
#define JOIST_MIG_WIN_READ	0u
#define JOIST_MIG_WIN_WRITE	1u
#define JOIST_MIG_WIN_ARGS	8u	/* windowed arrays a call, each way */
#define JOIST_MIG_PAGE		4096u

#define joist_mig_window __joist_mig_window
#define joist_mig_window_allocate __joist_mig_window_allocate
#define joist_mig_window_free __joist_mig_window_free
#define joist_mig_reply_read __joist_mig_reply_read
#define joist_mig_reply_write __joist_mig_reply_write

/* The calling thread's read or write window over BYTES at VA (0 bytes:
   none): 0, or not 0 if refused.  */
extern int joist_mig_window (unsigned int kind, const void *va,
			     size_t bytes);
/* Memory a write window may lie over (present, writable, in one of the
   task's regions), and its release: NULL if there is none, and the stubs
   then offer no write window.  */
extern void *joist_mig_window_allocate (size_t bytes);
extern void joist_mig_window_free (void *p, size_t bytes);
/* A server's copies, through the reply it holds for the call it serves:
   BYTES at OFF in the caller's read window to DST, or from SRC to OFF in
   its write window, at most JOIST_MIG_COPY_MAX; *DONE the bytes copied.
   0, or not 0 if refused.  */
extern int joist_mig_reply_read (uint64_t off, void *dst, size_t bytes,
				 size_t *done);
extern int joist_mig_reply_write (uint64_t off, const void *src,
				  size_t bytes, size_t *done);

/* The bytes B has left.  */
static inline size_t
joist_mig_room (const struct joist_mig_body *b)
{
  size_t start = joist_mig_align (b->at);
  return start > sizeof b->w ? 0 : sizeof b->w - start;
}

/* A client stub's windows for one call.  */
struct joist_mig_win
{
  unsigned int nin, nout;
  const void *in_p[JOIST_MIG_WIN_ARGS];
  size_t in_n[JOIST_MIG_WIN_ARGS];
  size_t in_total;
  size_t out_n[JOIST_MIG_WIN_ARGS];	/* the slices offered (0: none) */
  size_t out_off[JOIST_MIG_WIN_ARGS];
  size_t out_total;
  void *stage;			/* two in arrays or more, together */
  unsigned char *out;		/* the write window's memory */
  unsigned int set;		/* the windows set: bit 1 << kind */
};

static inline void
joist_mig_win_init (struct joist_mig_win *w)
{
  *w = (struct joist_mig_win) { 0 };
}

/* The next out array's slice of the write window, BYTES long (0: none
   offered).  Called at most JOIST_MIG_WIN_ARGS times.  */
static inline void
joist_mig_win_out (struct joist_mig_win *w, size_t bytes)
{
  size_t off = joist_mig_align (w->out_total);
  w->out_off[w->nout] = bytes != 0 ? off : 0;
  w->out_n[w->nout] = bytes;
  if (bytes != 0)
    w->out_total = off + bytes;
  w->nout++;
}

/* The write window's memory for the slices: without any, no slice is
   offered.  */
static inline void
joist_mig_win_alloc (struct joist_mig_win *w)
{
  if (w->out_total == 0)
    return;
  w->out = (unsigned char *) joist_mig_window_allocate (w->out_total);
  if (w->out == NULL)
    {
      for (unsigned int i = 0; i < w->nout; i++)
	w->out_n[i] = w->out_off[i] = 0;
      w->out_total = 0;
    }
}

/* An in array of BYTES at P through the read window: its offset there in
   *OFF.  -1 past what a call carries.  */
static inline int
joist_mig_win_in (struct joist_mig_win *w, const void *p, size_t bytes,
		  uint64_t *off)
{
  size_t o = joist_mig_align (w->in_total);
  if (w->nin == JOIST_MIG_WIN_ARGS || bytes == 0
      || bytes > JOIST_MIG_WINDOW_MAX || o > JOIST_MIG_WINDOW_MAX - bytes)
    return -1;
  w->in_p[w->nin] = p;
  w->in_n[w->nin] = bytes;
  w->nin++;
  w->in_total = o + bytes;
  *off = o;
  return 0;
}

/* Before the call: the read window over the in data (the caller's own
   array, a byte of each page read first, since a page not present stops
   the kernel's copy; two arrays or more staged together), the write
   window over its memory.  0, or a MIG error.  */
static inline int
joist_mig_win_open (struct joist_mig_win *w)
{
  if (w->nin == 1)
    {
      const volatile unsigned char *p = w->in_p[0];
      size_t n = w->in_n[0];
      size_t lead = JOIST_MIG_PAGE - (uintptr_t) p % JOIST_MIG_PAGE;
      (void) p[0];
      for (size_t i = lead; i < n; i += JOIST_MIG_PAGE)
	(void) p[i];
      if (joist_mig_window (JOIST_MIG_WIN_READ, w->in_p[0], n) != 0)
	return JOIST_MIG_ARRAY_TOO_LARGE;
      w->set |= 1u << JOIST_MIG_WIN_READ;
    }
  else if (w->nin > 1)
    {
      unsigned char *s = joist_mig_allocate (w->in_total);
      if (s == NULL)
	return JOIST_MIG_ARRAY_TOO_LARGE;
      w->stage = s;
      size_t o = 0;
      for (unsigned int i = 0; i < w->nin; i++)
	{
	  o = joist_mig_align (o);
	  memcpy (s + o, w->in_p[i], w->in_n[i]);
	  o += w->in_n[i];
	}
      if (joist_mig_window (JOIST_MIG_WIN_READ, s, w->in_total) != 0)
	return JOIST_MIG_ARRAY_TOO_LARGE;
      w->set |= 1u << JOIST_MIG_WIN_READ;
    }
  if (w->out != NULL)
    {
      if (joist_mig_window (JOIST_MIG_WIN_WRITE, w->out, w->out_total) != 0)
	return JOIST_MIG_ARRAY_TOO_LARGE;
      w->set |= 1u << JOIST_MIG_WIN_WRITE;
    }
  return 0;
}

/* After the call: both windows cleared.  */
static inline void
joist_mig_win_close (struct joist_mig_win *w)
{
  for (unsigned int k = 0; k < 2; k++)
    if (w->set & 1u << k)
      (void) joist_mig_window (k, NULL, 0);
  w->set = 0;
}

/* When the stub returns (its cleanup): the windows cleared, the memory
   freed.  */
static inline void
joist_mig_win_done (struct joist_mig_win *w)
{
  joist_mig_win_close (w);
  if (w->stage != NULL)
    {
      joist_mig_deallocate (w->stage, w->in_total);
      w->stage = NULL;
    }
  if (w->out != NULL)
    {
      joist_mig_window_free (w->out, w->out_total);
      w->out = NULL;
    }
}

/* A reply's windowed array, BYTES long at OFF, for slice I: where it is,
   or NULL if that isn't inside the slice offered.  */
static inline const void *
joist_mig_win_result (const struct joist_mig_win *w, unsigned int i,
		      uint64_t off, size_t bytes)
{
  if (w->out == NULL || i >= w->nout || w->out_n[i] == 0
      || off != w->out_off[i] || bytes > w->out_n[i])
    return NULL;
  return w->out + off;
}

/* A server stub's in array that came through the window: memory of its
   own, freed when the stub returns (its cleanup).  */
struct joist_mig_ool
{
  void *p;
  size_t n;
};

static inline void
joist_mig_ool_free (struct joist_mig_ool *o)
{
  if (o->p != NULL)
    {
      joist_mig_deallocate (o->p, o->n);
      o->p = NULL;
    }
}

/* O->N bytes at OFF in the caller's read window into memory of the
   stub's own, a copy call at a time: 0, or -1 (refused, or short).  */
static inline int
joist_mig_ool_read (struct joist_mig_ool *o, uint64_t off)
{
  if (o->n == 0 || o->n > JOIST_MIG_WINDOW_MAX || off > JOIST_MIG_WINDOW_MAX)
    return -1;
  o->p = joist_mig_allocate (o->n);
  if (o->p == NULL)
    return -1;
  for (size_t at = 0; at < o->n;)
    {
      size_t k = o->n - at < JOIST_MIG_COPY_MAX ? o->n - at
						 : JOIST_MIG_COPY_MAX;
      size_t done = 0;
      if (joist_mig_reply_read (off + at, (unsigned char *) o->p + at, k,
				&done) != 0 || done != k)
	return -1;
      at += k;
    }
  return 0;
}

/* BYTES from SRC to OFF in the caller's write window, a copy call at a
   time: 0, or -1 (refused, or short).  */
static inline int
joist_mig_write_all (uint64_t off, const void *src, size_t bytes)
{
  if (off > JOIST_MIG_WINDOW_MAX)
    return -1;
  for (size_t at = 0; at < bytes;)
    {
      size_t k = bytes - at < JOIST_MIG_COPY_MAX ? bytes - at
						 : JOIST_MIG_COPY_MAX;
      size_t done = 0;
      if (joist_mig_reply_write (off + at, (const unsigned char *) src + at,
				 k, &done) != 0 || done != k)
	return -1;
      at += k;
    }
  return 0;
}

#endif
